package com.fitpulse.model.entity;
import com.fitpulse.model.enums.ContentStatus; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*;
@Entity @Table(name="gyms") public class Gym {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private City city;
 @Column(nullable=false,length=150) private String name; @Column(nullable=false,unique=true,length=180) private String slug; @Column(nullable=false,length=3000) private String description; @Column(nullable=false,length=300) private String address;
 @Column(precision=9,scale=6) private BigDecimal latitude; @Column(precision=9,scale=6) private BigDecimal longitude; @Column(length=50) private String phone; @Column(length=500) private String websiteUrl;
 @Column(length=1000) private String openingHours; @Column(length=1500) private String services; @Column(length=1000) private String priceInfo; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private ContentStatus status=ContentStatus.DRAFT;
 @Column(nullable=false) private LocalDateTime createdAt; @Column(nullable=false) private LocalDateTime updatedAt; @OneToMany(mappedBy="gym",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER) @OrderBy("sortOrder asc") private List<GymPhoto> photos=new ArrayList<>();
 @PrePersist void create(){createdAt=updatedAt=LocalDateTime.now();} @PreUpdate void update(){updatedAt=LocalDateTime.now();}
 public Long getId(){return id;} public City getCity(){return city;} public void setCity(City v){city=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getSlug(){return slug;} public void setSlug(String v){slug=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public BigDecimal getLatitude(){return latitude;} public void setLatitude(BigDecimal v){latitude=v;} public BigDecimal getLongitude(){return longitude;} public void setLongitude(BigDecimal v){longitude=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getWebsiteUrl(){return websiteUrl;} public void setWebsiteUrl(String v){websiteUrl=v;} public String getOpeningHours(){return openingHours;} public void setOpeningHours(String v){openingHours=v;} public String getServices(){return services;} public void setServices(String v){services=v;} public String getPriceInfo(){return priceInfo;} public void setPriceInfo(String v){priceInfo=v;} public ContentStatus getStatus(){return status;} public void setStatus(ContentStatus v){status=v;} public List<GymPhoto> getPhotos(){return photos;}
}
